negativeExample:
import org.eclipse.jface.viewers.ListViewer;
import org.eclipse.jface.viewers.SelectionChangedEvent;
import org.eclipse.jface.viewers.ISelectionChangedListener;

public class MyClass {
    ListViewer listViewer = new ListViewer(null);
    Object otherObject = new Object();

    public MyClass() {
        // Lambda body is not a single method call on 'this' with the same parameter
        listViewer.addSelectionChangedListener(event -> {
            System.out.println(event);
            notifySelectionListeners(event);
        });
        // Method reference already used
        listViewer.addSelectionChangedListener(this::notifySelectionListeners);
        // Lambda refers to a method on another object
        listViewer.addSelectionChangedListener(e -> otherObject.toString());
    }

    private void notifySelectionListeners(SelectionChangedEvent event) {
        // do something
    }
}
